import{_ as d,C as r,o as i,c as l,a2 as e,E as o}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"交付与进度","description":"Hearth 已经交付什么、还缺什么，以及接下来按什么顺序收敛。","frontmatter":{"title":"交付与进度","description":"Hearth 已经交付什么、还缺什么，以及接下来按什么顺序收敛。","outline":[2,3]},"headers":[],"relativePath":"delivery/index.md","filePath":"delivery/index.md","lastUpdated":1793867008000}'),h={name:"delivery/index.md"};function n(s,t,c,p,m,b){const a=r("DocCardGrid");return i(),l("div",null,[t[0]||(t[0]=e('<h1 id="交付与进度" tabindex="-1">交付与进度 <a class="header-anchor" href="#交付与进度" aria-label="Permalink to &quot;交付与进度&quot;">​</a></h1><p class="lead">这不是一份只描述未来的路线图。它从已经跑通的闭环出发，记录哪些能力可以被代码和测试证明，哪些边界仍然留空，以及下一步按什么顺序补齐。</p><h2 id="一句话结论" tabindex="-1">一句话结论 <a class="header-anchor" href="#一句话结论" aria-label="Permalink to &quot;一句话结论&quot;">​</a></h2><p><strong>阶段一 MVP 已通过硬门槛；阶段二至六形成可运行的代码闭环与自动测试，但尚未完成真实用户、真实设备和长期运行验收。</strong></p><p>2026-11-06 的验证基线：<code>npm test</code> 通过 40 个测试文件、199 个测试；<code>npm run typecheck</code>、<code>npm run build</code> 和 <code>npm run docs:build</code> 通过。15 个第一阶段真实任务全部执行，13 个通过验收。</p><h2 id="六个阶段" tabindex="-1">六个阶段 <a class="header-anchor" href="#六个阶段" aria-label="Permalink to &quot;六个阶段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>状态</th><th>已经跑通</th><th>仍然留空</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/mvp.html">一 · 最小完整 MVP</a></td><td><strong>已验收</strong></td><td>15 项真实任务、13 项通过；任务、审批、产物、恢复与备份闭环</td><td>T07 未交付 PR；T08 外部评论等待用户批准</td></tr><tr><td><a href="/hearth-os/delivery/capabilities.html">二 · 日常内容工作</a></td><td>部分完成</td><td>本地文件、知识库、网页来源；文档提取；草稿、审批、本地发件箱与回执</td><td>邮件/日历账户未接入；真实发送未实现</td></tr><tr><td><a href="/hearth-os/delivery/capabilities.html">三 · 桌面操作</a></td><td>部分完成</td><td>Windows 配对、能力审批、观察、暂停/接管/交还、低风险输入与 UIA 动作</td><td>敏感区域遮挡、隔离桌面、高风险补偿</td></tr><tr><td><a href="/hearth-os/delivery/capabilities.html">四 · 主动服务与手机</a></td><td>部分完成</td><td>六类触发器、主动收件箱、接受/忽略/稍后/转任务、注意力预算</td><td>手机 PWA、配对、推送、远程审批与接管</td></tr><tr><td><a href="/hearth-os/delivery/capabilities.html">五 · 记忆与进化</a></td><td>部分完成</td><td>记忆候选/召回/纠正/冲突/遗忘/导出；方法评估/晋升/拒绝/回退</td><td>真实长期使用与采用前后生产对照</td></tr><tr><td><a href="/hearth-os/delivery/capabilities.html">六 · 多设备与长期运行</a></td><td>部分完成</td><td>增量同步、对端认证、租约与 epoch fencing、撤销、加密备份、健康维护</td><td>真实双设备切换、设备丢失演练、数周连续运行</td></tr></tbody></table><h2 id="如何理解-部分完成" tabindex="-1">如何理解“部分完成” <a class="header-anchor" href="#如何理解-部分完成" aria-label="Permalink to &quot;如何理解“部分完成”&quot;">​</a></h2><p>“部分完成”不是“页面已经做完”，也不是“功能已经交付”。它只表示：</p><ol><li>服务端、API 和投影已经有可运行实现。</li><li>自动测试覆盖了主要代码路径和关键边界。</li><li>仍然缺少真实账户、真实设备、真实用户任务或长期运行证据。</li></ol><p>因此，阶段二至六不会因为“代码合并”而自动变成“已验收”。每个阶段都需要单独的真实任务记录、失败演练和用户核对。</p><h2 id="三层交付" tabindex="-1">三层交付 <a class="header-anchor" href="#三层交付" aria-label="Permalink to &quot;三层交付&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>含义</th><th>当前状态</th></tr></thead><tbody><tr><td><strong>可运行</strong></td><td>本机可以启动，任务可以创建、执行和查看</td><td>已具备</td></tr><tr><td><strong>已验证</strong></td><td>自动测试、隔离实例或真实运行记录证明关键路径</td><td>阶段一已具备；阶段二至六部分具备</td></tr><tr><td><strong>已验收</strong></td><td>真实用户、真实设备或真实外部账户完成约定任务</td><td>阶段一已通过；阶段二至六未完成</td></tr></tbody></table><h2 id="为什么重写路线" tabindex="-1">为什么重写路线 <a class="header-anchor" href="#为什么重写路线" aria-label="Permalink to &quot;为什么重写路线&quot;">​</a></h2><p>旧路线用“六个阶段、24 个小阶段”描述尚未发生的实现顺序。项目已经开发了很大一部分，继续用未来时描述会掩盖两个问题：哪些能力其实已经可运行，哪些能力只完成了代码而没有完成验收。</p><p>新路线改成三层结构：</p><ul><li><strong>交付总览</strong>：先给出阶段状态和证据边界。</li><li><strong>能力状态</strong>：按阶段列出已实现、已验证和明确留空。</li><li><strong>剩余路线</strong>：只保留尚未完成的工作流，并为每条工作流定义退出条件。</li></ul><h2 id="继续阅读" tabindex="-1">继续阅读 <a class="header-anchor" href="#继续阅读" aria-label="Permalink to &quot;继续阅读&quot;">​</a></h2>',18)),o(a,{columns:2,items:[{no:"01",title:"第一阶段 MVP 验收",text:"15 个真实任务的结果、T07/T08 边界、G1–G9 验收基线与证据。",link:"/delivery/mvp"},{no:"02",title:"阶段二至六能力",text:"按小阶段列出已实现、已验证和明确留空的部分。",link:"/delivery/capabilities"},{no:"03",title:"剩余路线",text:"七条工作流、里程碑、退出条件，以及明确不做什么。",link:"/delivery/roadmap"},{no:"04",title:"验收与证据",text:"测试层级、证据规则、复现命令，以及“完成”的定义。",link:"/delivery/acceptance"}]}),t[1]||(t[1]=e('<h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>优先级不是继续铺更多功能，而是把已经存在的代码闭环变成可被真实使用证明的能力：</p><ol><li>接入真实邮件/日历账户，完成 10–15 个日常内容任务。</li><li>补桌面敏感区域遮挡、隔离桌面和高风险动作，完成至少 5 个桌面任务验收。</li><li>做手机入口和主动任务打扰验收。</li><li>用真实记忆和方法做采用前后对照。</li><li>做双设备切换、设备丢失和备份恢复演练。</li><li>完成数周连续运行、版本升级回退和 v1.0 验收。</li></ol><p>详细顺序和退出条件见<a href="/hearth-os/delivery/roadmap.html">剩余路线</a>。</p>',4))])}const f=d(h,[["render",n]]);export{u as __pageData,f as default};
